//! `arith` generated by `mlirformat tblgen` (`arith.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "arith.gen.rs"]
mod arith;

#[test]
fn arith_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.load(arith::ArithDialect);
    common::Fixtures::check_dialect(&opt, "arith");
}
